const TOKEN = process.env.PINTEREST_ACCESS_TOKEN;
const BOARD = process.env.PINTEREST_BOARD_ID;
const item = $input.all()[0].json;
const product = item.product;
const imgs = (product.images && product.images.length) ? product.images : [product.image];
const results = [];
for (const url of imgs) {
  const res = await fetch('https://api.pinterest.com/v5/pins', {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + TOKEN, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      board_id: BOARD,
      title: (product.title || '').slice(0, 100),
      description: item.draft,
      link: product.affiliateUrl,
      media: { source_type: 'image_url', url: url }
    })
  });
  results.push({ status: res.status, url });
}
return [{ json: { platform: 'pinterest', count: results.length, results } }];

const TOKEN = process.env.FACEBOOK_PAGE_TOKEN;
const PAGE = process.env.FACEBOOK_PAGE_ID || '61593917245819';
const item = $input.all()[0].json;
const product = item.product;
const imgs = (product.images && product.images.length) ? product.images : [product.image];
const results = [];
for (const url of imgs) {
  const res = await fetch('https://graph.facebook.com/v18.0/' + PAGE + '/photos', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ url: url, caption: item.draft + '\n' + product.affiliateUrl, access_token: TOKEN })
  });
  results.push({ status: res.status });
}
return [{ json: { platform: 'facebook', count: results.length, results } }];

if (process.env.GENERATE_VIDEO !== 'true' || !process.env.CREATOMATE_API_KEY) return [{ json: { skipped: true } }];
const product = $input.all()[0].json.product;
const imgs = (product.images && product.images.length) ? product.images : [product.image];
const res = await fetch('https://api.creatomate.com/v1/renders', {
  method: 'POST',
  headers: { Authorization: 'Bearer ' + process.env.CREATOMATE_API_KEY, 'Content-Type': 'application/json' },
  body: JSON.stringify({ source: { kind: 'slideshow', elements: imgs.map((u) => ({ source: u })) } })
});
const data = await res.json();
return [{ json: { videoUrl: data.url || (data[0] && data[0].url), renderId: data.id } }];

const item = $input.all()[0].json;
if (item.skipped || !item.videoUrl) return [{ json: { skipped: true } }];
const TOKEN = process.env.FACEBOOK_PAGE_TOKEN;
const PAGE = process.env.FACEBOOK_PAGE_ID || '61593917245819';
const fbres = await fetch('https://graph.facebook.com/v18.0/' + PAGE + '/videos', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ file_url: item.videoUrl, description: item.product ? item.product.title : '', access_token: TOKEN })
});
return [{ json: { platform: 'video', facebook: fbres.status, tiktokVideoUrl: item.videoUrl, nota: 'Para TikTok usa este videoUrl en Buffer (TikTok no tiene API abierta).' } }];
